WITH with_gaps AS (SELECT *, CASE WHEN event_time - LAG(event_time) OVER (PARTITION BY session_id ORDER BY event_time, id) > INTERVAL '60' DAY THEN 1 ELSE 0 END AS is_new_session FROM web_events), islands AS (SELECT *, SUM(is_new_session) OVER (PARTITION BY session_id ORDER BY event_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS burst_id FROM with_gaps) SELECT DATE_TRUNC('QUARTER', event_time) AS quarter_start, event_type, PERCENTILE_APPROX(duration_sec, 0.95) AS duration_sec_p95, STDDEV_SAMP(duration_sec) AS duration_sec_stddev, (UNIX_TIMESTAMP(MAX(event_time)) - UNIX_TIMESTAMP(MIN(event_time))) / 60 AS span_minutes, COUNT_IF(page = '/home') AS home_events, SORT_ARRAY(COLLECT_SET(event_type)) AS event_type_list FROM islands GROUP BY DATE_TRUNC('QUARTER', event_time), event_type;
